    return str(value)


def _is_inline_table(source, pattern):
    if not pattern:
        return False
    key = pattern.rsplit(".", 1)[-1]
    if key.endswith("]"):
        return False
    if re.search(r"(?m)^\s*" + re.escape(key) + r"\s*=\s*\{", source):
        return True
    # A table selected by array index retains inline-table formatting when
    # its containing value was written as an inline array of tables.
    parts = _path_parts(pattern)
