"""Basic TOML lint command implementation."""
import glob
import re
import sys

from tomltest import _find_eq, _key_parts, _parse, _strip_comment


def _duplicates(source):
    scopes = {"": {}}
    table = ""
    array_indices = {}
    for number, raw in enumerate(source.splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("[[") and line.endswith("]]" ):
            name = ".".join(_key_parts(line[2:-2]))
            array_indices[name] = array_indices.get(name, 0) + 1
            table = name + "#" + str(array_indices[name])
            scopes.setdefault(table, {})
            continue
        if line.startswith("[") and line.endswith("]"):
            table = ".".join(_key_parts(line[1:-1]))
            scopes.setdefault(table, {})
            continue
        eq = _find_eq(line)
        if eq < 0:
            continue
        parts = _key_parts(line[:eq].strip())
        key = ".".join(parts)
        scope = scopes.setdefault(table, {})
        if key in scope:
            return (scope[key], number, raw, parts[0])
        scope[key] = number
    return None


def _report_duplicate(source, filename, duplicate):
    first, second, raw, _key = duplicate
    lines = source.splitlines()
    width = len(str(second))
    print("error: conflicting keys", file=sys.stderr)
    print(f"  ┌─ {filename}:{second}:1", file=sys.stderr)
    print("  │", file=sys.stderr)
    print(f"{first:>{width}} │ {lines[first-1]}", file=sys.stderr)
    print("  │ " + "- duplicate found here", file=sys.stderr)
    print(f"{second:>{width}} │ {lines[second-1]}", file=sys.stderr)
    print("  │ " + "^ duplicate key", file=sys.stderr)


def run(args):
    files = []
    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ("-h", "--help"):
            sys.stdout.write("Lint TOML documents\n\nUsage: taplo lint [OPTIONS] [FILES]...\n")
            return 0
        if arg in ("-c", "--config", "--cache-path", "--schema", "--schema-catalog", "--colors"):
            i += 1
        elif arg.startswith("-") and arg != "-":
            pass
        else:
            files.append(arg)
        i += 1
    if not files:
        return 0
    paths = []
    for item in files:
        if item == "-":
            paths.append("-")
        else:
            paths.extend(glob.glob(item) or [item])
    result = 0
    for path in paths:
        try:
            source = sys.stdin.read() if path == "-" else open(path, encoding="utf-8").read()
            _parse(source)
            duplicate = _duplicates(source)
            if duplicate:
                _report_duplicate(source, path, duplicate)
                result = 1
        except OSError as exc:
            print(str(exc), file=sys.stderr)
            result = 1
        except Exception:
            print("error: invalid TOML", file=sys.stderr)
            result = 1
    return result

