    while True:
        headers = {}
        while True:
            line = stream.readline()
            if not line:
                return 0
            if line in (b"\r\n", b"\n"):
                break
            if b":" in line:
                k, v = line.decode("ascii", "replace").split(":", 1)
                headers[k.strip().lower()] = v.strip()
        try:
            size = int(headers.get("content-length", "0"))
            request = json.loads(stream.read(size).decode("utf-8"))
