"""Query and serialize TOML values for the get command."""
import fnmatch
import datetime
import math
import json
import re
import sys
import datetime
from decimal import Decimal, InvalidOperation

from tomltest import _parse


class TemporalValue(str):
    """TOML date/time value that remains a bare token in TOML output."""


class FloatValue(str):
    """A floating point value retaining its TOML spelling."""


def _preserve_temporals(value, raw_values):
    if isinstance(value, dict):
        return {k: _preserve_temporals(v, raw_values) for k, v in value.items()}
    if isinstance(value, list):
        return [_preserve_temporals(v, raw_values) for v in value]
    if isinstance(value, (datetime.datetime, datetime.date, datetime.time)):
        raw = raw_values.pop(0) if raw_values else value.isoformat()
        raw = re.sub(r"\.(\d+)", lambda m: ("." + m.group(1).rstrip("0")) if m.group(1).rstrip("0") else "", raw)
        return TemporalValue(raw)
    return value


def _float_spellings(source):
    # Mask strings and comments before looking for numeric tokens.
    chars = list(source)
    i = 0
    quote = None
    triple = False
    while i < len(chars):
        if quote is not None:
            if triple and source.startswith(quote * 3, i):
                chars[i:i + 3] = "   "
                i += 3
                quote = None
                triple = False
                continue
            c = source[i]
            chars[i] = " "
            if c == "\\" and quote == '"' and i + 1 < len(chars):
                chars[i + 1] = " "
                i += 2
                continue
            if not triple and c == quote:
                quote = None
            i += 1
            continue
        if source[i] == "#":
            while i < len(chars) and chars[i] != "\n":
                chars[i] = " "
                i += 1
            continue
        if source.startswith('"""', i) or source.startswith("'''", i):
            quote = source[i]
            triple = True
            chars[i:i + 3] = "   "
            i += 3
            continue
        if source[i] in "\"'":
            quote = source[i]
            chars[i] = " "
        i += 1
    masked = "".join(chars)
    temporal = re.compile(r"(?<![\w\"'])(?:\d{4}-\d\d-\d\d(?:[Tt ]\d\d:\d\d:\d\d(?:\.\d+)?(?:[Zz]|[+-]\d\d:\d\d)?)?|\d\d:\d\d:\d\d(?:\.\d+)?)(?![\w'])")
    masked = temporal.sub(lambda match: " " * len(match.group(0)), masked)
    token_re = re.compile(r"(?<![\w.])[+-]?(?:\d(?:_?\d)*(?:\.\d(?:_?\d)*)?|\.\d(?:_?\d)*)(?:[eE][+-]?\d(?:_?\d)*)?(?![\w.])")
    found = {}
    for match in token_re.finditer(masked):
        raw = source[match.start():match.end()]
        if "." not in raw and "e" not in raw.lower():
            continue
        try:
            found.setdefault(repr(float(raw.replace("_", ""))), []).append(raw)
        except ValueError:
            pass
    return found


def _preserve_floats(value, spellings):
    if isinstance(value, dict):
        return {key: _preserve_floats(child, spellings) for key, child in value.items()}
    if isinstance(value, list):
        return [_preserve_floats(child, spellings) for child in value]
    if isinstance(value, float):
        queue = spellings.get(repr(value), [])
        return FloatValue(queue.pop(0)) if queue else value
    return value


def _path_parts(pattern):
    parts = []
    buf = []
    i = 0
    while i < len(pattern):
        char = pattern[i]
        if char in "\"'":
            quote = char
            start = i
            i += 1
            escaped = False
            while i < len(pattern):
                c = pattern[i]
                if escaped:
                    escaped = False
                elif c == "\\" and quote == '"':
                    escaped = True
                elif c == quote:
                    break
                i += 1
            token = pattern[start:i + 1]
            try:
                decoded = json.loads(token) if quote == '"' else token[1:-1]
            except Exception:
                decoded = token[1:-1]
            buf.append(decoded)
            i += 1
            continue
        if char == ".":
            if buf:
                parts.append("".join(buf)); buf = []
            i += 1
            continue
        if char == "[":
            if buf:
                parts.append("".join(buf)); buf = []
            end = pattern.find("]", i + 1)
            if end < 0:
                buf.append(pattern[i:]); break
            inside = pattern[i + 1:end]
            if len(inside) >= 2 and inside[0] == inside[-1] and inside[0] in "\"'":
                inside = inside[1:-1]
            parts.append("*" if inside in ("", "*") else inside)
            i = end + 1
            continue
        buf.append(char)
        i += 1
    if buf:
        parts.append("".join(buf))
    return parts


def _select(value, parts):
    if not parts:
        return [value]
    head, tail = parts[0], parts[1:]
    selected = []
    if isinstance(value, dict):
        for key, child in value.items():
            if head == "*" or fnmatch.fnmatchcase(str(key), head):
                selected.extend(_select(child, tail))
    elif isinstance(value, list):
        if head == "*":
            for child in value:
                selected.extend(_select(child, tail))
        else:
            try:
                index = int(head)
                if 0 <= index < len(value):
                    selected.extend(_select(value[index], tail))
            except ValueError:
                pass
    return selected


def _toml_string(value):
    return json.dumps(value, ensure_ascii=False)


def _toml_key(key):
    key = str(key)
    return key if re.fullmatch(r"[A-Za-z0-9_-]+", key) else _toml_string(key)


def _toml_entry(key, value, source):
    rendered_key = _toml_key(key)
    if isinstance(value, str):
        raw_key = re.escape(str(key))
        match = re.search(r"(?m)^\s*" + raw_key + r"\s*=\s*(\"\"\"|''')", source)
        if match:
            quote = match.group(1)
            body_prefix = "\n" if source[match.end():].startswith("\n") else ""
            return f"{rendered_key} = {quote}{body_prefix}{value}{quote}"
    return f"{rendered_key} = {_toml(value, source=source)}"


def _toml_path(parts):
    return ".".join(_toml_key(part) for part in parts)



_DATE_TOKEN = re.compile(r"(?<![\w\"'])\d{4}-\d\d-\d\d(?:[Tt ]\d\d:\d\d:\d\d(?:\.\d+)?(?:[Zz]|[+-]\d\d:\d\d)?|\d\d:\d\d:\d\d(?:\.\d+)?)(?![\w'])")


def _temporal(value, source):
    for match in _DATE_TOKEN.finditer(source):
        raw = match.group(0)
        try:
            if re.match(r"^\d{4}-", raw):
                candidate = (datetime.datetime.fromisoformat(raw.replace("Z", "+00:00").replace("z", "+00:00"))
                             if "T" in raw or "t" in raw or " " in raw else datetime.date.fromisoformat(raw))
            else:
                candidate = datetime.time.fromisoformat(raw)
            if candidate == value:
                return raw
        except ValueError:
            pass
    return value.isoformat()


def _toml(value, indent=0, source=""):
    if isinstance(value, (datetime.datetime, datetime.date, datetime.time)):
        return _temporal(value, source)

    if isinstance(value, bool): return "true" if value else "false"
    if isinstance(value, FloatValue): return str(value)
    if isinstance(value, TemporalValue): return str(value)
    if isinstance(value, datetime.datetime):
        return value.isoformat().replace("+00:00", "Z")
    if isinstance(value, (datetime.date, datetime.time)):
        return value.isoformat()
    if isinstance(value, str): return _toml_string(value)
    if value is None: return ""
    if isinstance(value, float) and hasattr(value, "spelling"):
        return value.spelling
    if isinstance(value, list): return "[ " + ", ".join(_toml(v, indent, source) for v in value) + " ]"
    if isinstance(value, dict):
        return "{ " + ", ".join(f"{_toml_key(k)} = {_toml(v, indent, source)}" for k, v in value.items()) + " }"
    return str(value)



def _inline_root(source, key):
    return re.search(r"(?m)^\s*" + re.escape(key) + r"\s*=\s*(?:\{|\[\s*\{)", source) is not None


def _toml_document(document, source=""):
    """Serialize a complete document, retaining insertion order and table form."""
    chunks = []
    root_values = [(k, v) for k, v in document.items() if not isinstance(v, dict)
                   and not (isinstance(v, list) and v and all(isinstance(x, dict) for x in v))
                   or _inline_root(source, k)]
    if root_values:
        chunks.append("\n".join(_toml_entry(k, v, source) for k, v in root_values))

    def emit_table(name, table):
        lines = [f"[{_toml_path(name)}]"] if name else []
        children = []
        for key, value in table.items():
            if isinstance(value, dict):
                children.append((key, value))
            elif isinstance(value, list) and value and all(isinstance(x, dict) for x in value):
                children.append((key, value))
            else:
                lines.append(_toml_entry(key, value, source))
        if lines:
            chunks.append("\n".join(lines))
        for key, value in children:
            path = tuple(name) + (str(key),)
            if isinstance(value, list):
                for table_item in value:
                    emit_array_table(path, table_item)
            else:
                emit_table(path, value)

    def emit_array_table(name, table):
        lines = [f"[[{_toml_path(name)}]]"]
        children = []
        for key, value in table.items():
            if isinstance(value, dict): children.append((key, value))
            elif isinstance(value, list) and value and all(isinstance(x, dict) for x in value): children.append((key, value))

