def run(args):
    files = []
    schema_location = None
    schema_disabled = False
    config_path = None
    auto_config = True
    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ("-h", "--help"):
            import command_help
            command_help.write("lint")
            return 0
        if arg == "--schema":
            i += 1
            if i >= len(args):
                print("error: a value is required for '--schema <SCHEMA>' but none was supplied\n\nFor more information, try '--help'.", file=sys.stderr)
                return 2
            schema_location = args[i]
        elif arg.startswith("--schema="):
            schema_location = arg.split("=", 1)[1]
        elif arg == "--no-schema":
            schema_disabled = True
        elif arg in ("-c", "--config"):
            i += 1
            if i < len(args): config_path = args[i]
        elif arg.startswith("--config="):
            config_path = arg.split("=", 1)[1]
        elif arg == "--no-auto-config":
            auto_config = False
        elif arg in ("--cache-path", "--schema-catalog", "--colors"):
            i += 1
        elif arg.startswith("-") and arg != "-":
            pass
        else:
            files.append(arg)
        i += 1
    if files == ["-"]:
        collect_files([], "lint", config_path, auto_config)
        paths = ["-"]
    elif files:
        paths = collect_files(files, "lint", config_path, auto_config)
    else:
        paths = collect_files([], "lint", config_path, auto_config)
    result = 0
    schema = None
    if schema_location and not schema_disabled:
        if not urlparse(schema_location).scheme:
            print(f"error: invalid value '{schema_location}' for '--schema <SCHEMA>': relative URL without a base\n\nFor more information, try '--help'.", file=sys.stderr)
            return 2
        try:
            schema = _load_local_schema(schema_location)
        except Exception as exc:
            print(str(exc), file=sys.stderr)
            return 1
    for path in paths:
        try:
            source = sys.stdin.read() if path == "-" else open(path, encoding="utf-8").read()
            syntax = _syntax_error(source)
            if syntax:
                _report_syntax(source, path, syntax)
                result = 1
                continue
            _parse(source)
            if _has_syntax_error(source):
                print("error: invalid TOML", file=sys.stderr)
                result = 1
                continue
            duplicate = _duplicates(source)
            if duplicate:
                _report_duplicate(source, path, duplicate)
                result = 1
                continue
            if schema is not None:
                parsed = _parse(source)
                missing = [key for key in schema.get("required", [])
                           if isinstance(parsed, dict) and key not in parsed]
                for key in missing:
                    _report_required(source, path, key)
                if missing:
                    result = 1
                active_schema = ({key: value for key, value in schema.items() if key != "required"}
                                 if missing else schema)
                problems = _schema_errors(parsed, active_schema)
                for problem in problems:
                    _report_schema_problem(source, path, problem)
                    result = 1
        except OSError as exc:
            print(str(exc), file=sys.stderr)
            result = 1
        except Exception:
            print("error: invalid TOML", file=sys.stderr)
            result = 1
    return result

